    def test_fixture_compiles_deterministically(self):
        with tempfile.TemporaryDirectory() as directory:
            outputs = [Path(directory) / name for name in ("first", "second")]
            for output in outputs: result = self.compile(output); self.assertEqual(result.returncode, 0, result.stderr)
            for name in (CATALOG, LOCK):
                generated = (outputs[0] / name).read_bytes(); self.assertEqual(generated, (outputs[1] / name).read_bytes()); self.assertEqual(generated, (CORE / name).read_bytes())
